cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kd, int kh, int kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw)
{
  constexpr int Threads  = 128;
  constexpr int P_TILE   = 128;
  constexpr int KCHUNK   = 128;
  constexpr int CO_TILE  = 16;

  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int co_base = blockIdx.z * CO_TILE;
  const int p0 = blockIdx.x * P_TILE;
  const int p = p0 + tid;

  const int P_total = Dout * Hout * Wout;
  const bool pvalid = (p < P_total);

  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWci = (int64_t)Cout * kd * kh * kw;
  const int64_t sWco = (int64_t)kd * kh * kw;
  const int64_t sWkd = (int64_t)kh * kw;
  const int64_t sWkh = (int64_t)kw;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, kd, kh, kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );

  __shared__ T sW_raw[KCHUNK * CO_TILE];
  __shared__ int sCi[KCHUNK];
  __shared__ int sKz[KCHUNK];
  __shared__ int sKy[KCHUNK];
  __shared__ int sKx[KCHUNK];

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<KCHUNK>{}, Int<CO_TILE>{}),
      make_stride(Int<CO_TILE>{}, Int<1>{})
  );

  int od = 0, oh = 0, ow = 0;
  if (pvalid) {
    od = p / (Hout * Wout);
    int rem = p - od * (Hout * Wout);
    oh = rem / Wout;
    ow = rem - oh * Wout;
  }

  float acc[CO_TILE];
  #pragma unroll
  for (int cc = 0; cc < CO_TILE; ++cc) {
    int co = co_base + cc;
    float bv = 0.0f;
    if (B != nullptr && co < Cout) bv = (float)B[co];
    acc[cc] = bv;
  }

  const int K_total = Cin * kd * kh * kw;
  const bool unit_stride = (sd == 1 && sh == 1 && sw == 1);

  for (int k0 = 0; k0 < K_total; k0 += KCHUNK) {
    const int kc = min(KCHUNK, K_total - k0);

    for (int idx = tid; idx < KCHUNK; idx += Threads) {
      int kg = k0 + idx;
      bool kv = (kg < K_total);

      int ci = 0, kz = 0, ky = 0, kx = 0;
      if (kv) {
        kx = kg % kw;
        int r0 = kg / kw;
        ky = r0 % kh;
        int r1 = r0 / kh;
        kz = r1 % kd;
        ci = r1 / kd;
      }

      sCi[idx] = ci;
      sKz[idx] = kz;
      sKy[idx] = ky;
      sKx[idx] = kx;

      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        int co = co_base + cc;
        T wv = T(0);
        if (kv && co < Cout) {
          wv = mW(ci, co, kz, ky, kx);
        }
        sW(idx, cc) = wv;
      }
    }
    __syncthreads();

    if (pvalid) {
      for (int idx = 0; idx < kc; ++idx) {
        const int ci = sCi[idx];
        const int kz = sKz[idx];
        const int ky = sKy[idx];
        const int kx = sKx[idx];

        int id, ih, iw;
        bool valid;

        if (unit_stride) {
          id = od + pd - kz;
          ih = oh + ph - ky;
          iw = ow + pw - kx;
          valid = ((unsigned)id < (unsigned)Din) &&
                  ((unsigned)ih < (unsigned)Hin) &&
                  ((unsigned)iw < (unsigned)Win);
        } else {
          int nd = od + pd - kz;
          int nh = oh + ph - ky;
          int nw = ow + pw - kx;
          valid = false;
          id = ih = iw = 0;
          if (nd >= 0 && nh >= 0 && nw >= 0 &&
              (nd % sd) == 0 && (nh % sh) == 0 && (nw % sw) == 0) {
            id = nd / sd;
            ih = nh / sh;
            iw = nw / sw;
            valid = ((unsigned)id < (unsigned)Din) &&
                    ((unsigned)ih < (unsigned)Hin) &&
                    ((unsigned)iw < (unsigned)Win);
          }
        }

        if (valid) {
          const float xv = (float)mX(ci, id, ih, iw);
          #pragma unroll
          for (int cc = 0; cc < CO_TILE; ++cc) {
            acc[cc] += xv * (float)sW(idx, cc);
          }
        }
      }
    }
    __syncthreads();
  }

  if (pvalid) {
    #pragma unroll
    for (int cc = 0; cc < CO_TILE; ++cc) {
      int co = co_base + cc;
      if (co < Cout) {
        mY(co, od, oh, ow) = (T)acc[cc];
      }
    }
  }
}

torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride_d, int stride_h, int stride_w,
                                            int pad_d, int pad_h, int pad_w,
                                            int out_pad_d, int out_pad_h, int out_pad_w,
                                            int groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, Din, Hin, Win]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, kd, kh, kw]");
  TORCH_CHECK(groups == 1, "This CUTE kernel currently supports groups == 1");

  const int64_t N = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t Din = x.size(2);
  const int64_t Hin = x.size(3);
  const int64_t Win = x.size(4);

  const int64_t wCin = w.size(0);
  const int64_t Cout = w.size(1);
  const int64_t kd = w.size(2);
  const int64_t kh = w.size(3);
  const int64_t kw = w.size(4);

  TORCH_CHECK(wCin == Cin, "weight.size(0) must equal input channels");
  TORCH_CHECK(stride_d > 0 && stride_h > 0 && stride_w > 0, "strides must be positive");
  TORCH_CHECK(pad_d >= 0 && pad_h >= 0 && pad_w >= 0, "padding must be non-negative");
  TORCH_CHECK(out_pad_d >= 0 && out_pad_h >= 0 && out_pad_w >= 0, "output padding must be non-negative");

  const int64_t Dout = (Din - 1) * stride_d - 2 * pad_d + kd + out_pad_d;
  const int64_t Hout = (Hin - 1) * stride_h - 2 * pad_h + kh + out_pad_h;
  const int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + kw + out_pad_w;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed conv output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x_c.options());

  constexpr int Threads = 128;
  constexpr int P_TILE = 128;
  constexpr int CO_TILE = 16;

  const int64_t P_total = Dout * Hout * Wout;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + P_TILE - 1) / P_TILE),
      (unsigned)N,
      (unsigned)((Cout + CO_TILE - 1) / CO_TILE)
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv_transpose3d_tiled_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,
      (int)Cout, (int)Dout, (int)Hout, (int)Wout,
      (int)kd, (int)kh, (int)kw,
      stride_d, stride_h, stride_w,
      pad_d, pad_h, pad_w
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_tiled_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_tiled_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a single custom CUTE/CUDA kernel.
    Parameters are stored in self.conv_transpose3d so the module remains state_dict-compatible
    with the reference nn.ConvTranspose3d module.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: tuple = (1, 1, 1),
                 padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0),
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.stride = tuple(int(v) for v in stride)
        self.padding = tuple(int(v) for v in padding)
        self.output_padding = tuple(int(v) for v in output_padding)
        self.groups = int(groups)

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        return self._ext.conv_transpose3d_cute_forward(
            x.contiguous(),
            self.conv_transpose3d.weight.contiguous(),
            bias if bias is not None else None,
            int(self.stride[0]), int(self.stride[1]), int(self.stride[2]),
            int(self.padding[0]), int(self.padding[1]), int(self.padding[2]),
            int(self.output_padding[0]), int(self.output_padding[1]), int(self.output_padding[2]),
            int(self.groups),
        )

